191      public static Applicable checkAndLoadNative(Applicable defn, boolean isFunctionalMethod,
192                                                  com.sun.fortress.interpreter.evaluator.types.FType declarer) {
193          Option<Expr> optBody = NodeUtil.getBody(defn);
194          if (optBody.isNone()) return defn;
195          Expr body = optBody.unwrap();
196          Expr fn;
197          Expr arg;
198          if (body instanceof Juxt && ((Juxt) body).isTight()) {
199              List<Expr> juxts = ((Juxt) body).getExprs();
200              if (juxts.size() != 2) return defn;
201              fn = juxts.get(0);
202              arg = juxts.get(1);
203          } else if (body instanceof MathPrimary) {
204              MathPrimary mp = (MathPrimary) body;
205              List<MathItem> args = mp.getRest();
206              if (args.size() != 1) return defn;
207              fn = mp.getFront();
208              MathItem mi = args.get(0);
209              if (mi instanceof ExprMI) arg = ((ExprMI) mi).getExpr();
210              else return defn;
211          } else // (!(body instanceof TightJuxt || body instanceof MathPrimary))
212              return defn;
213          if (!(fn instanceof VarRef)) return defn;
214          if (!(arg instanceof StringLiteralExpr)) return defn;
215          Id name = ((VarRef) fn).getVarId();
216          if (!name.getText().equals("builtinPrimitive")) return defn;
217          String str = ((StringLiteralExpr) arg).getText();
218          String own = OWN_OPERATIONS.get(str);
219          if (own != null) str = own;
220          else if (str.startsWith(ARRAY_HELPERS)) str = ARRAY_OPERATIONS + str.substring(ARRAY_HELPERS.length());
221          Pair<String, Applicable> key = new Pair<String, Applicable>(str, defn);
222          synchronized (cache) {
223              NativeApp res = cache.get(key);
224              if (res != null) return res;
225              if (StaticNativeApp.isHelperString(str)) {
226                  Object found = StaticNativeApp.find(str, defn, declarer);
227                  if (found instanceof String) return bug(defn, (String) found);
228                  res = new StaticNativeApp((java.lang.reflect.Method) found, defn);
229                  res.init(defn, isFunctionalMethod);
230                  cache.put(key, res);
231                  return res;
232              }
233              try {
234                  // System.err.println("Loading primitive class "+str);
235                  Class nativeAct = Class.forName(str);
236                  res = (NativeApp) nativeAct.newInstance();
237                  res.init(defn, isFunctionalMethod);
238                  cache.put(key, res);
239                  return res;
240              }
241              catch (java.lang.ClassNotFoundException x) {
242                  return bug(defn, "Native class " + str + " not found.", x);
243              }
244              catch (java.lang.InstantiationException x) {
245                  return bug(defn, "Native class " + str + " has no nullary constructor.", x);
246              }
247              catch (java.lang.IllegalAccessException x) {
248                  return bug(defn, "Native class " + str + " cannot be accessed.", x);
249              }
250              catch (java.lang.ClassCastException x) {
251                  return bug(defn, "Native class " + str + " is not a NativeApp.", x);
